  copy {
    position: absolute;
    right: 0;
    bottom: 0;
    height: var(--spacing-8);
    padding-inline: var(--spacing-2);
    color: var(--color-on-surface-low);
    opacity: 0;

    &:focus-visible { opacity: 1; }
  }
}

.prompt {
  display: flex;
  width: 100%;
  height: 10rem;
  justify-content: center;
  background-color: var(--color-field);

  field { width: var(--spacing-prose); }
  textarea { padding-block: var(--spacing-8); }
}

.modal {
  position: fixed;
  inset: 0;
  display: flex;
  justify-content: center;
  pointer-events: none;

  backdrop { position: fixed; inset: 0; pointer-events: none; }
  content {
    position: fixed;
    z-index: 800;
    width: var(--spacing-prose);
    background-color: var(--color-surface-high);
    pointer-events: auto;
  }
  search {
    display: flex;
    width: 100%;
    max-height: var(--spacing-sm);
    flex-direction: column;
  }
  search_query {
    width: 100%;
    height: var(--spacing-12);
    background-color: var(--color-surface-higher);
  }
  search_results { flex-grow: 1; }
  search_result {
    display: flex;
    width: 100%;
    height: var(--spacing-8);
    align-items: center;
    padding-inline: var(--spacing-8);

    &[focus] { background-color: var(--color-focus); }
  }
  search_result_label { flex-grow: 1; white-space: nowrap; text-overflow: ellipsis; }
  search_result_info {
    flex-shrink: 0;
    color: var(--color-on-surface-low);
    white-space: nowrap;
    text-overflow: ellipsis;
  }
}

.textarea {
  width: 100%;
  height: fit-content;
  border-radius: var(--rounded-md);

  &:focus-visible {
    border-radius: var(--rounded-md);
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }
}

.input {
  width: 100%;
  height: 100%;
  padding: var(--spacing-4);
  border-radius: var(--rounded-md);
  font-size: 1.125rem;
  line-height: 1.75rem;

  &:focus-visible {
    border-radius: var(--rounded-md);
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }
}

.scroll {
  position: relative;
  display: flex;
  flex: 1;

  content { flex: 1; overflow: auto; }
  vertical_scrollbar { position: absolute; top: 0; right: 0; bottom: 0; z-index: 100; }
  vertical_track {
    width: 0.75rem;
    height: 100%;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] { opacity: 1; }
  }
  vertical_thumb { width: 100%; background-color: var(--color-scrollbar-thumb); }
  horizontal_scrollbar { position: absolute; right: 0; bottom: 0; left: 0; z-index: 100; }
  horizontal_track {
    width: 100%;
    height: 0.75rem;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] { opacity: 1; }
  }
  horizontal_thumb { height: 100%; background-color: var(--color-scrollbar-thumb); }
}

